% mathsmap-diagram-colours {"version":1,"kind":"graph","base":[],"semantic":[],"reference":"pages 13–14 Q2 solution panels"}
\begin{tikzpicture}
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\foreach \lab/\a/\h/\k/\c/\col/\row in {a/1/3/-9/0/0/0}{
\pgfmathsetmacro{\r}{sqrt(abs(\k)+4)}\pgfmathsetmacro{\xl}{min(0,\h-\r)-.4}\pgfmathsetmacro{\xr}{max(0,\h+\r)+.4}
\pgfmathsetmacro{\yl}{min(0,\k,\c)-3}\pgfmathsetmacro{\yr}{max(0,\k,\c)+3}\pgfmathsetmacro{\xu}{4/(\xr-\xl)}\pgfmathsetmacro{\yu}{3.2/(\yr-\yl)}
\begin{scope}[shift={(5.6*\col,-4.9*\row)}]\node[anchor=west] at (0,3.8){\lab};
\begin{scope}[x=\xu cm,y=\yu cm,shift={(-\xl,-\yl)}]
\draw[->,line width=.5pt] (\xl,0)--(\xr,0) node[right]{$x$};\draw[->,line width=.5pt] (0,\yl)--(0,\yr) node[above]{$y$};\draw[dashed,line width=.4pt] (\h,\yl)--(\h,\yr);
\begin{scope}\clip (\xl,\yl) rectangle (\xr,\yr);\draw[line width=.8pt,domain=\xl:\xr,samples=90] plot (\x,{\a*(\x-\h)^2+\k});\end{scope}
\fill (\h,\k) circle (1pt) node[below right] {$V$};\fill (0,\c) circle (1pt) node[above left] {$Y$};
\end{scope}\end{scope}}
\end{tikzpicture}

